result.output:
   Display type is lowercase — Broadside's single most distinctive rule.
   =========================================== */
.slide {
    font-family: Barlow, "Helvetica Neue", sans-serif;
    color: var(--fg);
    background: var(--ink);
    font-variant-numeric: tabular-nums;
    -webkit-font-smoothing: antialiased;
}

.display {
    font-size: 250px;
    font-weight: 900;
    line-height: 0.88;
    letter-spacing: -0.04em;
    margin: 0;
}

.h1 {
    font-size: 144px;
    font-weight: 800;
    line-height: 0.9;
    letter-spacing: -0.03em;
    margin: 0;
}

.h2 {
    font-size: 86px;
    font-weight: 700;
    line-height: 1.06;
    letter-spacing: -0.02em;
    margin: 0;
}

.h3 {
    font-size: 54px;
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: -0.01em;
    margin: 0;
}

.lead {
    font-size: 31px;
    font-weight: 400;
    line-height: 1.5;
    margin: 0;
    color: var(--fg);
}

.body {
    font-size: 23px;
    font-weight: 400;
    line-height: 1.6;
    margin: 0;
    color: var(--fg-muted);
}

.caption {
    font-size: 17px;
    font-weight: 400;
    line-height: 1.5;
    margin: 0;
    color: var(--fg-muted);
}

.label,
.kicker,
.tag,
.num {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 14px;
    font-weight: 500;
    line-height: 1;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

.kicker { color: var(--signal); }
.label  { color: var(--fg-faint); }

.tag {
    display: inline-block;
    color: var(--signal);
    border: 1px solid var(--signal);
    padding: 0.42em 0.85em;
}

.mono {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-variant-numeric: tabular-nums;
}

/* ===========================================
   SLIDE SHELL — padded frame + optional chrome bars
   Chrome is suppressed on declarative slides (cover, statement, quote, end).
   =========================================== */
.pad {
    position: absolute;
    inset: 0;
    padding: var(--pad-y) var(--pad-x);
    display: flex;
    flex-direction: column;
}

.slide-chrome,
.slide-foot {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex: 0 0 auto;
}

.slide-chrome {
    padding-bottom: var(--gap-sm);
    border-bottom: 1px solid var(--border);
    margin-bottom: var(--gap-lg);
}

.slide-foot {
    padding-top: var(--gap-sm);
    border-top: 1px solid var(--border);
    margin-top: auto;
}

.slide-body {
    flex: 1 1 auto;
    min-height: 0;
    display: flex;
    flex-direction: column;
    padding-bottom: 12px;
}

/* ===========================================
   SIGNAL REGISTER — the flooded declaration slides
   Every Barlow display/heading element is forced to ink. No light text
   on signal: this is the "ink on signal" rule, absolute.
   =========================================== */
.slide.signal { background: var(--signal); color: var(--on-sig); }
.slide.signal .display,
.slide.signal .h1,
.slide.signal .h2,
.slide.signal .h3 { color: var(--on-sig); }
.slide.signal .lead    { color: var(--on-sig-body); }
.slide.signal .body    { color: var(--on-sig-body); }
.slide.signal .caption { color: var(--on-sig-hint); }
.slide.signal .kicker  { color: var(--on-sig-label); }
.slide.signal .label   { color: var(--on-sig-hint); }
.slide.signal .rule    { background: var(--on-sig); }
.slide.signal .slide-chrome,
.slide.signal .slide-foot { border-color: var(--on-sig-border); }
.slide.signal .tag {
    color: var(--on-sig-label);
    border-color: var(--on-sig-faint);
}

/* ===========================================
   COMPONENTS
   Flat plane only. Hierarchy comes from type weight, size, and 1px rules.
   =========================================== */

/* Stub accent rule — the system's only ornament */
.rule {
    width: 36px;
    height: 2px;
    background: var(--signal);
    flex: 0 0 auto;
}

.rule-full {
    width: 100%;
    height: 1px;
    background: var(--border);
    flex: 0 0 auto;
}

/* Catalogue-style slide number, anchored on declaration slides */
.broadside-num {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 21px;
    font-weight: 500;
    letter-spacing: 0.1em;
    color: var(--fg-faint);
}
.slide.signal .broadside-num { color: var(--on-sig-faint); }

/* Stat card — top border only, big numeral, label, mono note */
.stats {
    display: grid;
    gap: 0 46px;
}
.stat {
    border-top: 1px solid var(--border);
    padding: var(--gap-md) var(--gap-md) 0 0;
}
.slide.signal .stat { border-top-color: var(--on-sig-border); }

.stat-value {
    font-size: 106px;
    font-weight: 900;
    line-height: 1;
    letter-spacing: -0.04em;
    color: var(--signal);
    display: block;
}
.slide.signal .stat-value { color: var(--on-sig); }

.stat-value.sm { font-size: 78px; }

.stat-label {
    font-size: 23px;
    line-height: 1.45;
    color: var(--fg);
    margin-top: 14px;
}
.slide.signal .stat-label { color: var(--on-sig); }

.stat-note {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--fg-faint);
    margin-top: 12px;
    line-height: 1.5;
}
.slide.signal .stat-note { color: var(--on-sig-hint); }

/* Bullet list — mono slash marker, capped at three items */
.list { list-style: none; margin: 0; padding: 0; }
.list li {
    position: relative;
    padding-left: 42px;
    font-size: 31px;
    line-height: 1.5;
    color: var(--fg);
    margin-bottom: 26px;
}
.list li:last-child { margin-bottom: 0; }
.list li::before {
    content: "/";
    position: absolute;
    left: 0;
    top: 1px;
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-weight: 700;
    font-size: 27px;
    color: var(--signal);
}
.slide.signal .list li { color: var(--on-sig); }
.slide.signal .list li::before { color: var(--on-sig-faint); }

.list li b {
    font-weight: 600;
    color: var(--fg);
}
.list li span {
    display: block;
    font-size: 21px;
    line-height: 1.55;
    color: var(--fg-muted);
    margin-top: 4px;
}

/* Compare panels — the payoff side flooded in signal */
.compare {
    display: grid;
    grid-template-columns: 1fr 1fr;
    flex: 1 1 auto;
    min-height: 0;
}
.compare-left {
    padding-right: 58px;
    border-right: 1px solid var(--border);
    display: flex;
    flex-direction: column;
}
.compare-right {
    padding-left: 58px;
    display: flex;
    flex-direction: column;
}
.compare-right.filled {
    background: var(--signal);
    padding: 44px 52px;
    margin-left: 58px;
    border: none;
}
.compare-right.filled .h3,
.compare-right.filled .list li { color: var(--on-sig); }
.compare-right.filled .kicker { color: var(--on-sig-label); }
.compare-right.filled .list li::before { color: var(--on-sig-faint); }
.compare-right.filled .list li span { color: var(--on-sig-body); }
.compare-right.filled .rule { background: var(--on-sig); }

/* Image frames — flat, 1px hairline, no radius */
.figure {
    border: 1px solid var(--border);
    background: var(--ink);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}
.figure img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    max-width: none;
    max-height: none;
}
.figure.contain img { object-fit: contain; }

.figcap {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--fg-faint);
    margin-top: 12px;
}

/* Source note — the mono footer voice */
.source {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--fg-faint);
    line-height: 1.6;
}
.slide.signal .source { color: var(--on-sig-hint); }

/* Verdict chips — semantic colour, meaning only */
.chip {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 0.35em 0.7em;
    border: 1px solid currentColor;
}
.chip.pass { color: var(--pass); }
.chip.fail { color: var(--fail); }
.chip.warn { color: var(--warn); }

/* Spec table — hairline rows, mono values */
.spec-rows { display: flex; flex-direction: column; }
.spec-row {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: baseline;
    gap: 24px;
    padding: 15px 0;
    border-bottom: 1px solid var(--border);
}
.spec-row:first-child { border-top: 1px solid var(--border); }
.spec-row dt {
    font-size: 21px;
    color: var(--fg-muted);
}
.spec-row dd {
    margin: 0;
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 22px;
    font-weight: 500;
    color: var(--fg);
    font-variant-numeric: tabular-nums;
}
.spec-row dd.hi { color: var(--signal); }

/* Cost ledger — three columns, hairline rows, the Kevin column in signal.
   Measured and modelled figures are separated by the assumptions line below. */
.ledger { display: flex; flex-direction: column; }
.lrow {
    display: grid;
    grid-template-columns: 1fr 0.62fr 0.62fr;
    align-items: baseline;
    gap: 26px;
    padding: 15px 0;
    border-bottom: 1px solid var(--border);
}
.lrow.lhead { padding-bottom: 11px; border-bottom: 1px solid var(--border); }
.lk { font-size: 22px; color: var(--fg-muted); }
.lv {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 23px;
    font-weight: 500;
    color: var(--fg);
    text-align: right;
    font-variant-numeric: tabular-nums;
}
.lv.hi { color: var(--signal); }

.assump {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    line-height: 1.75;
    letter-spacing: 0.06em;
    color: var(--fg-faint);
    border-left: 1px solid var(--border);
    padding-left: 18px;
}

/* The result slide packs nine rows beside a chart — tighten the rhythm
   without dropping any of the run's numbers. */
.s-run .spec-row { padding: 10px 0; }
.s-run .spec-row dt { font-size: 20px; }
.s-run .spec-row dd { font-size: 21px; }

/* Two lists side by side, one of them inside a filled panel: tighten the
   leading so the panel clears the foot rule. */
.s-compare .list li { margin-bottom: 20px; font-size: 29px; }
.s-compare .list li span { font-size: 20px; }

/* Pipeline diagram — flat boxes, hairline connectors */
.pipeline {
    display: flex;
    align-items: stretch;
    gap: 0;
    width: 100%;
}
.pnode {
    flex: 1 1 0;
    border: 1px solid var(--border);
    border-right: none;
    padding: 30px 22px 32px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    background: var(--ink-alt);
}
.pnode:last-child { border-right: 1px solid var(--border); }
.pnode.agent { border-color: var(--signal); background: rgba(76, 157, 255, 0.09); }
.pnode.agent + .pnode { border-left-color: var(--signal); }
.pnode .pk {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 12px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--fg-faint);
}
.pnode.agent .pk { color: var(--signal); }
.pnode .pt {
    font-size: 24px;
    font-weight: 600;
    line-height: 1.15;
    color: var(--fg);
    letter-spacing: -0.01em;
}
.pnode .pd {
    font-size: 16px;
    line-height: 1.45;
    color: var(--fg-muted);
}

.feedback {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-top: 18px;
}
.feedback .fbline {
    flex: 1 1 auto;
    height: 1px;
    background: linear-gradient(90deg, var(--signal), var(--signal) 70%, transparent);
}
.feedback .fbtext {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--signal);
}

/* Quote */
.quote-mark {
    font-size: 192px;
    font-weight: 900;
    line-height: 0.6;
    color: var(--signal);
    display: block;
    height: 118px;
}
.quote-text {
    font-size: 68px;
    font-weight: 700;
    line-height: 1.14;
    letter-spacing: -0.02em;
    max-width: 78%;
    margin: 0;
    color: var(--fg);
}
.quote-attr {
    margin-top: var(--gap-lg);
}
.quote-attr .qn {
    font-size: 24px;
    font-weight: 600;
    color: var(--fg);
}
.quote-attr .qr {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--fg-faint);
    margin-top: 7px;
}

/* Stage numerals on the pipeline, and the measured solve times given the
   weight they deserve — they are the reason the loop exists. */
.pnode .pn {
    color: var(--signal);
    font-weight: 600;
    margin-right: 0.85em;
    opacity: 0.85;
}
.tick { border-top: 1px solid var(--border); padding-top: 16px; }
.tv {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 64px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.03em;
    color: var(--signal);
    font-variant-numeric: tabular-nums;
}
.tick .label { margin-top: 14px; }

/* The candidate sweep draws itself: one faint response per simulation, in
   the order the loop produced them, then the accepted design on top. */
.s11 .cand {
    fill: none;
    stroke: #394054;
    stroke-width: 1.5;
    stroke-linejoin: round;
    stroke-dasharray: 1600;
    stroke-dashoffset: 1600;

    stroke-dashoffset: 1600;
}
.s11 .win {
    fill: none;
    stroke: var(--signal);
    stroke-width: 3.5;
    stroke-linejoin: round;
    stroke-linecap: round;
    stroke-dasharray: 1600;
    stroke-dashoffset: 1600;
}
[data-anim].run .s11 .cand {
    animation: draw-on 0.5s linear forwards;
    animation-delay: calc(0.45s + var(--i) * 0.055s);
}
[data-anim].run .s11 .win {
    animation: draw-on 1.1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    animation-delay: 2.15s;
}
@keyframes draw-on { to { stroke-dashoffset: 0; } }

.motion .print-frame { display: none; }

@media print {
    .s11 .cand,
    .s11 .win { stroke-dashoffset: 0 !important; }

    /* Chrome refuses to paint a subtree that contains a <video> at all —
       display:none is not enough, so the element is pulled from the DOM on
       beforeprint and the poster frame takes its place. */
    .motion .print-frame { display: block !important; }
}

/* A looping render of the real device geometry. Poster carries print and
   any browser that blocks autoplay. */
.motion {
    border: 1px solid var(--border);
    background: var(--ink);
    overflow: hidden;
    line-height: 0;
}
.motion video,
.motion img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    display: block;
    max-width: none;
    max-height: none;
}

/* Team portraits — four photographs taken in four different rooms, under
   four different lights. Monochrome is what makes them read as one row
   rather than four snapshots; drop the filter for colour. */
.portrait {
    width: 100%;
    aspect-ratio: 1 / 1;
    border: 1px solid var(--border);
    background: var(--ink-alt);
    overflow: hidden;
}
.portrait img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    max-width: none;
    max-height: none;
    filter: grayscale(1) contrast(1.05) brightness(1.02);
}

/* Team */
.team {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 40px;
    align-items: start;
}
.member { border-top: 1px solid var(--border); padding-top: var(--gap-md); }
.member .mn {
    font-size: 40px;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.1;
    color: var(--fg);
}
.member .mr {
    font-size: 21px;
    line-height: 1.45;
    color: var(--signal);
    margin-top: 12px;
}
.member .ml {
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 13px;
    letter-spacing: 0.06em;
    color: var(--fg-faint);
    margin-top: 16px;
}

/* Brand mark */
.mark { width: 152px; height: 152px; color: var(--on-sig); flex: 0 0 auto; }
.mark.dark { color: var(--fg); }

/* ===========================================
   ENTRY ANIMATIONS
   One orchestrated load per slide, staggered. Replays on every activation.
   =========================================== */
[data-anim] { opacity: 0; }
[data-anim].run {
    animation-duration: 0.62s;
    animation-timing-function: var(--ease-enter);
    animation-fill-mode: both;
}
[data-anim="fade-up"].run     { animation-name: fadeUp; }
[data-anim="fade-in"].run     { animation-name: fadeIn; }
[data-anim="reveal-right"].run{ animation-name: revealRight; }
[data-anim="scale-in"].run    { animation-name: scaleIn; }

@keyframes fadeUp {
    from { opacity: 0; transform: translateY(26px); }
    to   { opacity: 1; transform: none; }
}
@keyframes fadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}
@keyframes revealRight {
    from { opacity: 0; transform: translateX(-34px); }
    to   { opacity: 1; transform: none; }
}
@keyframes scaleIn {
    from { opacity: 0; transform: scale(0.965); }
    to   { opacity: 1; transform: none; }
}

/* Slide transition — the deck cross-dissolves at Broadside's slide ease */
.slide { transition: opacity 0.5s var(--ease-slide), visibility 0s linear 0.5s; }
.slide.active { transition: opacity 0.5s var(--ease-slide), visibility 0s; }

/* ===========================================
   PRESENTER CHROME — outside the slide design system
   =========================================== */
.deck-controls {
    display: flex;
    align-items: center;
    gap: 10px;
    opacity: 0.34;
    transition: opacity 0.25s ease;
}
.deck-controls:hover { opacity: 1; }
.dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: #4a5164;
    border: none;
    padding: 0;
    cursor: pointer;
    transition: background 0.2s ease, transform 0.2s ease;
}
.dot.on { background: var(--signal); transform: scale(1.35); }

.counter {
    position: fixed;
    right: 22px;
    bottom: 20px;
    z-index: 1000;
    font-family: "IBM Plex Mono", ui-monospace, monospace;
    font-size: 12px;
    letter-spacing: 0.14em;
    color: #4a5164;
}

@media print {
    .counter { display: none !important; }
    [data-anim] { opacity: 1 !important; }
}
</style>
